/* GitAtlas — command database
   Every entry: c = command, d = what it does (plain English),
   e = when you would actually use it, x = optional worked example. */

const ATLAS = [
{
  id: "setup",
  label: "Setup & identity",
  tag: "config",
  blurb: "Tell Git who you are and how it should behave. Do this once per machine and every repo you touch inherits it.",
  commands: [
    { c: 'git --version', d: 'Prints the Git version installed on your machine.', e: 'First thing to run after installing Git, or when a tutorial says "requires Git 2.23+" and you need to check whether switch and restore exist on your system.' },
    { c: 'git config --global user.name "Your Full Name"', d: 'Sets the author name stamped on every commit you make on this computer.', e: 'Run it once after installing Git. If you skip it, Git either refuses to commit or stamps commits with a machine-generated name that looks wrong forever in the history.' },
    { c: 'git config --global user.email "you@example.com"', d: 'Sets the author email on your commits. GitHub matches this email to your account to attribute the commit to you.', e: 'If your contribution graph on GitHub is empty even though you have been pushing, this is almost always the reason — the commit email is not registered on your GitHub account.' },
    { c: 'git config --global init.defaultBranch main', d: 'Makes every new repository start on a branch called main instead of the old default, master.', e: 'Run once so that git init matches GitHub, which creates main by default. Saves you renaming the branch on every new project.' },
    { c: 'git config --global core.editor "code --wait"', d: 'Chooses which text editor Git opens for commit messages, interactive rebases and merge conflict prompts.', e: 'Use it if Git keeps dropping you into Vim and you cannot get out. --wait tells VS Code to block until you close the tab, which Git needs.', x: 'git config --global core.editor "code --wait"   # VS Code\ngit config --global core.editor "nano"           # Nano\ngit config --global core.editor "vim"            # Vim' },
    { c: 'git config --global core.autocrlf true', d: 'Controls how Git handles line endings between Windows (CRLF) and Linux/macOS (LF).', e: 'On Windows use true. On macOS/Linux use input. Without it, a teammate on another OS sees every line of a file marked as changed even when nothing was edited.', x: 'git config --global core.autocrlf true    # Windows\ngit config --global core.autocrlf input   # macOS / Linux' },
    { c: 'git config --global color.ui auto', d: 'Turns on coloured output for status, diff and branch listings.', e: 'Makes diffs readable at a glance — additions green, deletions red — instead of a wall of identical grey text.' },
    { c: 'git config --global pull.rebase false', d: 'Decides whether git pull merges (false) or rebases (true) the incoming commits.', e: 'Set it explicitly, because newer Git versions print a warning and refuse to pull until you choose. Pick false for a shared team branch, true if you like a straight, linear history.' },
    { c: 'git config --global push.default simple', d: 'Makes a bare git push only push the current branch to its matching upstream branch.', e: 'Safety setting: it stops you from accidentally pushing every local branch you have to the server in one command.' },
    { c: 'git config --global rerere.enabled true', d: 'Reuse Recorded Resolution — Git memorises how you resolved a conflict and replays that resolution automatically if the same conflict shows up again.', e: 'A long-lived feature branch that you rebase onto main every day will hit the same conflict repeatedly. Turn rerere on and you solve it once.' },
    { c: 'git config --global credential.helper manager', d: 'Stores your GitHub credentials securely so you are not asked for a token on every push.', e: 'Use manager on Windows, osxkeychain on macOS, cache on Linux. Avoid store — it writes your token to a plain text file.', x: 'git config --global credential.helper manager      # Windows\ngit config --global credential.helper osxkeychain  # macOS\ngit config --global credential.helper "cache --timeout=3600"  # Linux, 1 hour' },
    { c: 'git config --global core.filemode false', d: 'Tells Git to ignore Unix file-permission changes (like 755 to 644).', e: 'Useful when a project is shared between Windows and Linux, or lives on a mounted drive, and Git keeps reporting every file as modified for no visible reason.' },
    { c: 'git config --global commit.template ~/.gitmessage', d: 'Pre-fills your editor with a commit message skeleton every time you commit.', e: 'Great for teams that follow Conventional Commits — the template reminds everyone of the format instead of relying on memory.', x: '# ~/.gitmessage\n# <type>(<scope>): <subject>\n#\n# <body: what changed and why, wrap at 72 chars>\n#\n# <footer: BREAKING CHANGE, Closes #123>\n# types: feat fix docs style refactor test chore' },
    { c: 'git config --global core.excludesfile ~/.gitignore_global', d: 'Points Git at a personal ignore file that applies to every repository on your machine.', e: 'Put OS and editor junk here — .DS_Store, Thumbs.db, .idea/, .vscode/ — so you never have to add them to a project .gitignore that your teammates share.' },
    { c: 'git config --list', d: 'Shows every configuration value Git is currently using, merged from system, global and repo level.', e: 'Your first debugging step when Git behaves unexpectedly — you can usually spot the stray setting causing it.', x: 'git config --list            # everything\ngit config --global --list   # only your machine-wide settings\ngit config --local --list    # only this repository\ngit config --show-origin --get user.email  # which file set this?' },
    { c: 'git config user.email "work@company.com"', d: 'Without --global, the setting applies only to the repository you are standing in.', e: 'Perfect when personal projects use your Gmail address but company repos must be committed with your work address.' },
    { c: 'git config --global --unset alias.st', d: 'Deletes a single configuration key.', e: 'Cleaning up an alias or a setting you copied from a blog post and no longer want.' },
    { c: 'git help merge', d: 'Opens the full manual page for any Git command.', e: 'Faster and more accurate than searching the web when you need every flag a command accepts. git merge --help does the same thing.' }
  ]
},
{
  id: "aliases",
  label: "Aliases & shortcuts",
  tag: "config",
  blurb: "Aliases turn long, forgettable commands into two-letter muscle memory. These are the ones that earn their keep.",
  commands: [
    { c: 'git config --global alias.st status', d: 'Creates a shortcut, so git st now runs git status.', e: 'You will type status hundreds of times a day. The same pattern works for co=checkout, br=branch, ci=commit.', x: 'git config --global alias.co checkout\ngit config --global alias.br branch\ngit config --global alias.ci commit\ngit config --global alias.st status' },
    { c: "git config --global alias.graph 'log --oneline --graph --decorate --all'", d: 'One command that draws your entire commit history as an ASCII graph with branch and tag labels.', e: 'The fastest way to understand "where am I and how did these branches diverge" without opening a GUI.' },
    { c: "git config --global alias.lg \"log --color --graph --pretty=format:'%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)<%an>%Creset' --abbrev-commit\"", d: 'A prettier commit graph: short hash, refs, subject, relative time and author, all colour coded.', e: 'The single most-copied Git alias on the internet, and worth it — you will use git lg instead of git log forever after.' },
    { c: "git config --global alias.unstage 'reset HEAD --'", d: 'Makes git unstage file.txt remove a file from the staging area without touching your edits.', e: 'Easier to remember than reset HEAD -- when you accidentally git add a file you were not ready to commit.' },
    { c: "git config --global alias.last 'log -1 HEAD --stat'", d: 'Shows the most recent commit plus the list of files it touched.', e: 'A quick "what did I just commit?" check before you push.' },
    { c: 'git config --global alias.amend "commit --amend --no-edit"', d: 'Folds your currently staged changes into the previous commit without opening an editor.', e: 'You committed, then immediately noticed a typo. Fix it, git add, git amend — history stays clean.' },
    { c: 'git config --global alias.force "push --force-with-lease"', d: 'Aliases the dangerous force push to the safe version of it.', e: 'Training-wheels move: you type git force out of habit, but you get the version that refuses to overwrite a teammate\'s work.' },
    { c: 'git config --global alias.contributors "shortlog -sn"', d: 'Lists everyone who has committed to the repo, sorted by number of commits.', e: 'Handy when you join a codebase and want to know who to ask about it.' },
    { c: 'git config --global alias.root "rev-parse --show-toplevel"', d: 'Prints the absolute path of the repository root, wherever you are inside it.', e: 'Use it in scripts, or as cd $(git root) to jump back to the top of a deep folder tree.' },
    { c: 'git config --get-regexp alias', d: 'Lists every alias you have defined.', e: 'You set up aliases six months ago and forgot what they were called. This is how you find them again.' },
    { c: 'git config --global alias.undo "reset --soft HEAD~1"', d: 'Undoes the last commit but keeps all its changes staged and ready.', e: 'You committed too early, or with the wrong message. git undo puts you right back where you were before committing.' },
    { c: 'git config --global alias.cleanup "!git branch --merged | grep -v \'\\*\\|main\\|develop\' | xargs -n 1 git branch -d"', d: 'A shell alias (the ! prefix runs a shell command) that deletes every local branch already merged into your current branch, except main and develop.', e: 'Run it monthly to clear out the twenty dead feature branches cluttering git branch.' }
  ]
},
{
  id: "start",
  label: "Starting a repository",
  tag: "basics",
  blurb: "Every project begins one of two ways: you create a repository, or you copy one that already exists.",
  commands: [
    { c: 'git init', d: 'Turns the current folder into a Git repository by creating a hidden .git directory.', e: 'You have written some code locally and now want version control on it. Run git init in the project folder, then add, commit and push to a new empty GitHub repo.' },
    { c: 'git init my-project', d: 'Creates a new folder and initialises a repository inside it in one step.', e: 'Starting a brand-new project from scratch when the folder does not exist yet.' },
    { c: 'git init --bare shared-repo.git', d: 'Creates a repository with no working files — only Git\'s internal data. Nobody edits code in it; people push to it.', e: 'This is what a server-side repository looks like. Use it to host a private repo on your own VPS instead of GitHub.' },
    { c: 'git clone https://github.com/user/repo.git', d: 'Downloads a full copy of a remote repository, including all branches and the complete history, and sets up origin automatically.', e: 'The command you use to get someone else\'s project onto your machine so you can run and modify it.' },
    { c: 'git clone git@github.com:user/repo.git', d: 'Same as above but over SSH, using your SSH key instead of a password or token.', e: 'Preferred for repos you push to daily — no token prompts, and it works well with 2FA on your GitHub account.' },
    { c: 'git clone repo-url my-folder', d: 'Clones into a folder name of your choosing rather than the repository\'s own name.', e: 'You are cloning the same repo twice to compare two branches side by side, so you need distinct folder names.' },
    { c: 'git clone --depth 1 repo-url', d: 'A shallow clone: downloads only the most recent commit instead of the entire history.', e: 'CI pipelines and Docker builds use this constantly — it can cut a 400 MB clone down to 20 MB when you only need the current code.' },
    { c: 'git clone --branch develop repo-url', d: 'Clones the repository and checks out the given branch or tag instead of the default one.', e: 'The team works on develop and main is only for releases, so you land on the right branch immediately.' },
    { c: 'git clone --single-branch --branch main repo-url', d: 'Fetches only one branch and ignores all the others.', e: 'Big monorepo with 300 stale branches — you only care about main, so skip downloading the rest.' },
    { c: 'git clone --recursive repo-url', d: 'Clones the repository and all of its submodules in one pass.', e: 'Without it, submodule folders arrive empty and the build fails with confusing "file not found" errors.' },
    { c: 'git clone --filter=blob:limit=1m repo-url', d: 'A partial clone: skips downloading files larger than 1 MB until you actually check them out.', e: 'Repositories full of design assets or datasets clone in seconds instead of an hour, and the big files stream in on demand.' },
    { c: 'git clone --mirror repo-url', d: 'Makes an exact bare copy of every ref in the remote — branches, tags, notes, everything.', e: 'The correct way to back up or migrate a repository from GitLab to GitHub without losing any history.', x: 'git clone --mirror https://old-host.com/team/repo.git\ncd repo.git\ngit push --mirror https://github.com/you/repo.git' }
  ]
},
{
  id: "staging",
  label: "Staging changes",
  tag: "basics",
  blurb: "The staging area is Git's shopping basket. You choose exactly what goes into the next commit before you make it.",
  commands: [
    { c: 'git status', d: 'Shows which files are modified, which are staged for the next commit, and which are untracked.', e: 'Run it constantly. It is the single most useful command in Git and also tells you what to type next.' },
    { c: 'git status -s', d: 'The short format — two-column codes instead of paragraphs of explanation.', e: 'Once you know the codes (M modified, A added, ?? untracked, the left column is staged and the right is unstaged) this fits a 50-file change on one screen.' },
    { c: 'git status --porcelain', d: 'A stable, machine-readable version of status designed for scripts.', e: 'Use it in a shell script or pre-commit hook: if git status --porcelain returns nothing, the working tree is clean.' },
    { c: 'git status --ignored', d: 'Also lists the files that .gitignore is currently hiding.', e: 'Confirms your .gitignore is actually working, and shows you what would be lost if you ran git clean -fx.' },
    { c: 'git add file.txt', d: 'Stages a specific file so its current contents go into the next commit.', e: 'You fixed a bug in one file and changed unrelated formatting in another. Stage only the bug fix so the commit stays focused.' },
    { c: 'git add .', d: 'Stages every new and modified file from the current directory downwards.', e: 'The everyday command. Just check git status first so you do not sweep up a .env file or a 200 MB build folder.' },
    { c: 'git add -A', d: 'Stages everything across the whole repository, including deletions, no matter which folder you are standing in.', e: 'Use it after a large refactor where you moved and deleted files, so Git records the removals too.' },
    { c: 'git add -u', d: 'Stages modifications and deletions of already-tracked files, but ignores brand-new untracked files.', e: 'You want to commit your edits but leave a handful of new scratch files out of the repo for now.' },
    { c: 'git add -p', d: 'Interactive patch mode: Git walks you through each chunk of change and asks whether to stage it.', e: 'The professional habit. One file has both a bug fix and a debug print — stage the fix, skip the print, and commit something reviewable.', x: 'git add -p\n#  y  stage this chunk        n  skip it\n#  s  split into smaller chunks  e  edit the chunk by hand\n#  a  stage this and all later chunks in the file\n#  q  quit                     ?  help' },
    { c: 'git add -i', d: 'Opens a menu-driven interactive staging session: status, update, revert, patch, diff.', e: 'A gentler front end than -p when you have a messy working tree and want to sort it out file by file.' },
    { c: 'git add "*.js"', d: 'Stages every file matching a pattern, across all directories.', e: 'Ran a formatter over the whole project and only want to commit the JavaScript changes in this commit.' },
    { c: 'git add -N file.txt', d: 'Records the intent to track a new file without staging its contents yet.', e: 'Makes a brand-new file show up in git diff, so you can review it with git add -p before staging any of it.' },
    { c: 'git add --chmod=+x script.sh', d: 'Stages the file and marks it executable in Git\'s index.', e: 'Your deploy script works locally but fails with "permission denied" on the server — this is the fix, and it works even from Windows.' },
    { c: 'git rm file.txt', d: 'Deletes the file from disk and stages the deletion.', e: 'Removing a file for real. Plain rm followed by git add -A does the same thing, but this is one step.' },
    { c: 'git rm --cached .env', d: 'Stops tracking a file in Git but keeps it on your disk.', e: 'The rescue command when you accidentally committed .env or node_modules. Run this, add the path to .gitignore, then commit.', x: 'git rm --cached .env\necho ".env" >> .gitignore\ngit commit -m "chore: stop tracking .env"\n# note: the secret is still in past commits — rotate it' },
    { c: 'git rm -r --cached node_modules', d: 'Untracks an entire directory recursively while leaving it on disk.', e: 'The classic "I forgot .gitignore before my first commit" cleanup for node_modules, venv or build folders.' },
    { c: 'git mv old.txt new.txt', d: 'Renames or moves a file and stages the change in one step.', e: 'Git tracks content rather than names, so a plain rename also works — but this keeps your status output tidy and explicit.' },
    { c: 'git restore --staged file.txt', d: 'Removes a file from the staging area, keeping your edits in the working directory. The modern replacement for git reset HEAD.', e: 'You staged something too early. This unstages it without any risk of losing work.' },
    { c: 'git restore file.txt', d: 'Throws away uncommitted changes to a file and restores it to the last committed version.', e: 'You experimented in a file and want it back exactly as it was. Careful — those edits are gone for good.' },
    { c: 'git restore --source=HEAD~3 file.txt', d: 'Pulls an older version of a single file into your working directory.', e: 'A function worked three commits ago and is broken now. Grab the old copy to compare, without rolling back the whole project.' }
  ]
},
{
  id: "commit",
  label: "Committing",
  tag: "basics",
  blurb: "A commit is a permanent, named snapshot of your project. Small, focused commits with honest messages are what make history useful.",
  commands: [
    { c: 'git commit -m "Add login validation"', d: 'Records everything currently staged as a new commit with the given message.', e: 'The core of Git. Write the subject in the imperative — "Add", "Fix", "Remove" — as if completing the sentence "This commit will…".' },
    { c: 'git commit', d: 'Opens your editor so you can write a full message: a short subject line, a blank line, then the body.', e: 'Use this for anything non-trivial. The body is where you explain why the change was made, which is what future readers actually need.' },
    { c: 'git commit -am "Fix header spacing"', d: 'Stages all modified tracked files and commits them in one step. It does not include new untracked files.', e: 'Quick fixes where you already know every change belongs in the commit.' },
    { c: 'git commit -v', d: 'Shows the full diff of what you are committing inside the editor.', e: 'A built-in self-review. You will catch stray console.log lines and leftover TODOs before they reach the pull request.' },
    { c: 'git commit --amend -m "Better message"', d: 'Replaces the previous commit with a new one, letting you change the message and add staged changes.', e: 'You wrote "fix stuff" and want something meaningful — as long as you have not pushed yet.' },
    { c: 'git commit --amend --no-edit', d: 'Folds staged changes into the previous commit, keeping the existing message.', e: 'You forgot one file. Instead of an ugly "oops forgot a file" commit, add it to the one you just made.', x: 'git add forgotten-file.js\ngit commit --amend --no-edit\n# already pushed? then:\ngit push --force-with-lease' },
    { c: 'git commit --allow-empty -m "chore: trigger CI"', d: 'Creates a commit that changes nothing.', e: 'Your CI pipeline only runs on a push and you need to re-run it without touching code.' },
    { c: 'git commit --no-verify -m "wip"', d: 'Skips the pre-commit and commit-msg hooks.', e: 'Escape hatch when a linter hook is broken and blocking you. Do not make a habit of it — hooks exist to catch real problems.' },
    { c: 'git commit --fixup abc1234', d: 'Creates a specially-marked commit that says "this belongs inside commit abc1234".', e: 'A reviewer asks for a change to an earlier commit in your branch. Make a fixup, then run an autosquash rebase to fold it in cleanly.', x: 'git commit --fixup abc1234\ngit rebase -i --autosquash abc1234~1\n# Git pre-orders the todo list for you' },
    { c: 'git commit --squash abc1234', d: 'Like --fixup, but keeps your new message so you can edit the combined message during the rebase.', e: 'When the folded-in change is significant enough that the original commit message needs updating too.' },
    { c: 'git commit -S -m "Signed release"', d: 'Signs the commit with your GPG key, producing a Verified badge on GitHub.', e: 'Required in many companies and open-source projects to prove a commit genuinely came from you.' },
    { c: 'git commit --date="2024-01-15T09:00:00" -m "Backdated"', d: 'Sets the author date of the commit to a specific time.', e: 'Reconstructing a history when you are importing an old project that was never under version control.' },
    { c: 'git commit --author="Jane Doe <jane@example.com>" -m "Apply Jane\'s patch"', d: 'Credits someone else as the author while you remain the committer.', e: 'You are applying a patch a contributor emailed you and want the history to reflect who actually wrote it.' },
    { c: 'git commit -m "feat(auth): add TOTP two-factor login"', d: 'A Conventional Commits message: type, optional scope, then a short imperative subject.', e: 'Machine-readable messages let tools auto-generate changelogs and decide version bumps.', x: 'feat:     a new feature            -> minor version\nfix:      a bug fix                -> patch version\ndocs:     documentation only\nrefactor: no behaviour change\ntest:     tests only\nchore:    build, deps, tooling\n\nBREAKING CHANGE: in the footer     -> major version' }
  ]
},
{
  id: "ignore",
  label: "Ignoring & attributes",
  tag: "basics",
  blurb: "What you keep out of a repository matters as much as what you put in. Secrets, dependencies and build output do not belong in Git.",
  commands: [
    { c: 'echo "node_modules/" >> .gitignore', d: 'Adds a pattern to .gitignore so Git stops offering to track anything matching it.', e: 'The first file you should create in any project. Ignore dependencies, build output, logs and every environment file.', x: '# .gitignore essentials\nnode_modules/\ndist/\nbuild/\n.env\n.env.*\n!.env.example\n*.log\n__pycache__/\n.venv/\ntarget/\n.DS_Store\n.idea/\n.vscode/' },
    { c: 'git check-ignore -v path/to/file', d: 'Tells you which ignore rule, in which file, is hiding a given path.', e: 'You added a file, Git says nothing happened, and you cannot work out why. This names the exact line responsible.' },
    { c: 'git add -f build/report.html', d: 'Forces Git to track a file even though .gitignore excludes it.', e: 'The dist folder is ignored, but you genuinely need one generated file committed for a GitHub Pages deploy.' },
    { c: 'git ls-files', d: 'Lists every file Git is currently tracking.', e: 'Fast sanity check before pushing a new project: if node_modules shows up here, stop and fix it now.', x: 'git ls-files | wc -l                 # how many tracked files\ngit ls-files --others --ignored --exclude-standard   # what is being ignored' },
    { c: 'echo "*.psd binary" >> .gitattributes', d: '.gitattributes tells Git how to treat particular file types — binary, text, diff behaviour, line endings.', e: 'Stops Git from trying to produce a text diff of a Photoshop file, and prevents corruption from line-ending conversion.', x: '# .gitattributes\n* text=auto\n*.sh text eol=lf\n*.bat text eol=crlf\n*.png binary\n*.pdf binary\npackage-lock.json linguist-generated=true\ndocs/* linguist-documentation' },
    { c: 'echo "dist/* linguist-vendored" >> .gitattributes', d: 'Tells GitHub\'s language detector to exclude certain paths from the repository language statistics.', e: 'Your Python project shows as 90% JavaScript because of a bundled vendor folder. This fixes the language bar on your repo page.' }
  ]
},
{
  id: "history",
  label: "Reading history",
  tag: "inspect",
  blurb: "git log is a search engine for your project's past. These flags turn a wall of text into an answer.",
  commands: [
    { c: 'git log', d: 'Shows the full commit history of the current branch, newest first.', e: 'The starting point. Press q to quit the pager, space to scroll.' },
    { c: 'git log --oneline', d: 'Compresses each commit to a short hash and its subject line.', e: 'The everyday view. Twenty commits fit on a screen instead of two.' },
    { c: 'git log --oneline --graph --decorate --all', d: 'Draws every branch in the repository as an ASCII graph with branch and tag labels attached.', e: 'The single best command for understanding a tangled repository — you can see exactly where branches split and merged.' },
    { c: 'git log --stat', d: 'Adds a per-commit summary of which files changed and how many lines were added or removed.', e: 'Scanning for the commit that touched a particular file, or spotting the commit that accidentally reformatted 4,000 lines.' },
    { c: 'git log -p', d: 'Shows the complete diff introduced by each commit.', e: 'Reviewing a colleague\'s work locally, or tracing exactly how a function evolved over time.' },
    { c: 'git log -5', d: 'Limits output to the most recent five commits.', e: 'Combine with --oneline for a fast "what happened today" summary.' },
    { c: 'git log --author="Arman"', d: 'Filters history to commits by a particular author (matches on substring).', e: 'Reconstructing what you personally worked on last sprint for a standup or a report.' },
    { c: 'git log --since="2 weeks ago" --until="yesterday"', d: 'Filters commits by date. Accepts human phrases as well as exact dates.', e: 'Building release notes covering a specific window of time.' },
    { c: 'git log --grep="login"', d: 'Searches commit messages for a phrase.', e: 'Finding the commit that mentions the ticket number or feature you are investigating.' },
    { c: 'git log -S"calculateTotal"', d: 'The pickaxe: finds commits where the number of occurrences of a string changed — that is, where it was added or deleted.', e: 'The best way to answer "when was this function introduced, and when did somebody delete it?"' },
    { c: 'git log -G"regex_pattern"', d: 'Like -S but matches a regular expression anywhere in the diff text.', e: 'Hunting down every commit that ever touched a line containing an API key pattern or a deprecated call.' },
    { c: 'git log --follow app.js', d: 'Shows a file\'s history and keeps following it across renames.', e: 'You renamed the file six months ago and plain git log stops at the rename. --follow walks straight through it.' },
    { c: 'git log -L 40,60:app.js', d: 'Shows the history of just a specific line range in a file.', e: 'Laser-focused debugging: "who has ever touched these twenty lines, and why?"' },
    { c: 'git log main..feature', d: 'Lists commits that exist on feature but not on main.', e: 'Exactly what your pull request will contain. Run it before opening the PR to check nothing unexpected is in there.' },
    { c: 'git log main...feature --left-right', d: 'Shows commits unique to either side of the two branches, marking which side each belongs to.', e: 'Understanding how far two branches have diverged before you attempt a merge.' },
    { c: 'git log --no-merges', d: 'Hides merge commits so you only see real work.', e: 'Generating a changelog from a busy repository where half the history is merge noise.' },
    { c: 'git log --merges', d: 'Shows only merge commits.', e: 'Auditing when features actually landed on main, rather than when they were written.' },
    { c: 'git log --reverse --oneline', d: 'Prints history oldest first.', e: 'Reading a project from the beginning to understand how it was built up.' },
    { c: 'git log --pretty=format:"%h | %an | %ar | %s"', d: 'Builds a custom output format from placeholders.', e: 'Exporting history into a spreadsheet or generating a release changelog in exactly the shape you want.', x: '%H  full hash      %h  short hash\n%an author name    %ae author email\n%ad author date    %ar relative date\n%s  subject        %b  body\n%d  ref names      %Cred %Cgreen %Creset  colours' },
    { c: 'git shortlog -sn', d: 'Groups commits by author and shows a count for each, sorted by volume.', e: 'A one-line contributor leaderboard — useful for READMEs and for finding the right person to review a change.' },
    { c: 'git log --all --grep="fix" --since="1 month ago" --oneline', d: 'Filters can be stacked; by default they combine, and --all-match requires every one to match.', e: 'Answering a precise question like "which bug fixes landed on any branch in the last month?"' }
  ]
},
{
  id: "inspect",
  label: "Inspecting & searching",
  tag: "inspect",
  blurb: "Diff, blame and grep answer the three questions you actually have: what changed, who changed it, and where is it.",
  commands: [
    { c: 'git diff', d: 'Shows changes in your working directory that are not yet staged.', e: 'Read this before every git add. It is your last chance to spot a debug statement you left in.' },
    { c: 'git diff --staged', d: 'Shows what is staged and therefore about to be committed. Also spelled --cached.', e: 'The final review right before you type git commit.' },
    { c: 'git diff HEAD', d: 'Shows everything you have changed since the last commit, staged and unstaged together.', e: 'A complete picture of your uncommitted work in one view.' },
    { c: 'git diff main..feature', d: 'Compares the tips of two branches directly.', e: 'Seeing the full set of differences between a release branch and production.' },
    { c: 'git diff main...feature', d: 'Three dots: compares feature against the point where it branched off main.', e: 'This is what GitHub shows in a pull request. It ignores changes that landed on main after you branched, so you only see your own work.' },
    { c: 'git diff --name-only', d: 'Lists just the filenames that changed, without the content.', e: 'Feeding a list of changed files into a linter or test runner in a CI script.' },
    { c: 'git diff --name-status', d: 'Lists filenames with a letter showing how each changed: A added, M modified, D deleted, R renamed.', e: 'A quick structural overview of a large change set.' },
    { c: 'git diff --stat', d: 'Shows a per-file bar chart of insertions and deletions.', e: 'Judging the size of a change before you commit to reviewing it.' },
    { c: 'git diff --color-words', d: 'Highlights the individual words that changed instead of marking whole lines.', e: 'Reviewing prose, documentation or a reformatted config file where line-level diffs are unreadable.' },
    { c: 'git diff --ignore-all-space', d: 'Ignores whitespace differences entirely.', e: 'Someone reindented a file and the diff shows 500 changed lines. This reveals the three lines that actually changed.' },
    { c: 'git diff HEAD~3 HEAD -- src/', d: 'Restricts a diff to a specific path.', e: 'Checking what happened to just the src folder over the last three commits.' },
    { c: 'git show HEAD', d: 'Displays a single commit: its metadata and its full diff.', e: 'Your fastest "what exactly did that commit do?" lookup.' },
    { c: 'git show abc1234:src/app.js', d: 'Prints the entire contents of a file exactly as it was at a given commit.', e: 'Recovering a working version of a file you broke, without checking out the old commit.', x: 'git show abc1234:src/app.js > app-old.js\ndiff app-old.js src/app.js' },
    { c: 'git show --stat HEAD', d: 'Shows the commit metadata and a file-change summary without the full diff.', e: 'When you want the shape of a commit, not every line of it.' },
    { c: 'git blame file.js', d: 'Annotates every line of a file with the commit, author and date that last touched it.', e: 'You found a strange line of code. Blame tells you who wrote it and, more usefully, which commit message explains why.' },
    { c: 'git blame -L 40,60 file.js', d: 'Blames only a specific range of lines.', e: 'Faster and far more readable than blaming a 2,000-line file.' },
    { c: 'git blame -w -C file.js', d: 'Ignores whitespace-only changes and detects lines that were moved or copied from elsewhere.', e: 'Cuts through a reformatting commit to find the person who really wrote the logic.' },
    { c: 'git grep "TODO"', d: 'Searches the contents of tracked files. Much faster than grep -r because it skips ignored folders.', e: 'Finding every TODO in the codebase without wading through node_modules.', x: 'git grep -n "apiKey"              # show line numbers\ngit grep -i "password"            # case insensitive\ngit grep "useState" -- "*.jsx"    # limit to a file type\ngit grep "config" v1.0.0          # search an old tag' },
    { c: 'git bisect start', d: 'Begins a binary search through history to find the commit that introduced a bug.', e: 'The feature worked in v1.2 and is broken now, with 400 commits in between. Bisect finds the culprit in about nine steps.', x: 'git bisect start\ngit bisect bad                 # current commit is broken\ngit bisect good v1.2.0         # this tag worked\n# Git checks out a middle commit — test it, then:\ngit bisect good   OR   git bisect bad\n# repeat until Git names the first bad commit\ngit bisect reset               # return to where you started' },
    { c: 'git bisect run npm test', d: 'Automates bisect by running a command at each step and using its exit code to decide good or bad.', e: 'Fully hands-off bug hunting — walk away and come back to the exact commit that broke your test suite.' },
    { c: 'git describe --tags', d: 'Names the current commit relative to the nearest tag, like v1.2.0-14-gabc1234.', e: 'Perfect for stamping a build with a human-readable version number in CI.' },
    { c: 'git rev-parse HEAD', d: 'Prints the full SHA hash of the current commit.', e: 'Recording the exact commit in a deployment log or embedding it in a health-check endpoint.' },
    { c: 'git count-objects -vH', d: 'Reports how many objects the repository holds and how much disk space they use.', e: 'Diagnosing why a clone takes forever — usually a large binary committed years ago.' }
  ]
}
,
{
  id: "branch",
  label: "Branching",
  tag: "branching",
  blurb: "A branch is just a movable label pointing at a commit. That is why creating one is instant and free.",
  commands: [
    { c: 'git branch', d: 'Lists your local branches and marks the current one with an asterisk.', e: 'Quick orientation before you start work.' },
    { c: 'git branch -a', d: 'Lists local branches plus every remote-tracking branch Git knows about.', e: 'Checking whether a teammate has already pushed the branch you were about to create.' },
    { c: 'git branch -vv', d: 'Shows each branch with its last commit and which upstream branch it tracks, including ahead/behind counts.', e: 'Answers "am I ahead of origin, behind it, or both?" for every branch at once.' },
    { c: 'git branch --sort=-committerdate', d: 'Sorts branches by most recent activity instead of alphabetically.', e: 'Finding the branch you were working on last Friday when you have thirty of them.' },
    { c: 'git branch feature-login', d: 'Creates a branch at the current commit but leaves you where you are.', e: 'Bookmarking the current state before you try something risky on the branch you are already on.' },
    { c: 'git switch -c feature-login', d: 'Creates a branch and switches to it. The modern, clearer replacement for checkout -b.', e: 'The standard way to start a new piece of work. Branch from an up-to-date main.', x: 'git switch main\ngit pull\ngit switch -c feat/user-profile' },
    { c: 'git checkout -b feature-login', d: 'The older syntax that does the same thing as switch -c.', e: 'Still everywhere in documentation and works in every Git version, so worth knowing both.' },
    { c: 'git switch main', d: 'Moves you to an existing branch, updating your files to match it.', e: 'Git refuses if you have uncommitted changes that would be overwritten — commit or stash first.' },
    { c: 'git switch -', d: 'Jumps back to the branch you were on previously.', e: 'Bouncing between a feature branch and main while comparing behaviour. The same trick as cd - in a shell.' },
    { c: 'git switch -c hotfix HEAD~3', d: 'Creates a branch starting from a specific earlier commit rather than the current tip.', e: 'You need to patch the code as it was before the last three commits broke it.' },
    { c: 'git switch -c hotfix-1.2.1 v1.2.0', d: 'Creates a branch from a tag.', e: 'The standard hotfix workflow: branch from the exact released version, fix the bug, tag a patch release.' },
    { c: 'git switch -c local-copy origin/feature', d: 'Creates a local branch that tracks a branch existing only on the remote.', e: 'Checking out a colleague\'s branch to test their work before approving the pull request.' },
    { c: 'git switch --detach abc1234', d: 'Checks out a commit directly without being on any branch (detached HEAD).', e: 'Inspecting or running an old commit. Any commits you make here are unreachable unless you create a branch, so switch back or branch out when done.' },
    { c: 'git checkout --orphan gh-pages', d: 'Creates a branch with no history at all — a completely fresh start.', e: 'Building a documentation or GitHub Pages branch that should not carry the source history.' },
    { c: 'git branch -m new-name', d: 'Renames the branch you are currently on.', e: 'You called it fix and it grew into a feature. Rename before pushing so the remote stays tidy.', x: 'git branch -m feat/proper-name\ngit push origin -u feat/proper-name\ngit push origin --delete old-name' },
    { c: 'git branch -d feature-login', d: 'Deletes a local branch, but only if it has already been merged.', e: 'Routine cleanup after a pull request is merged. The safety check is the point — it refuses to lose unmerged work.' },
    { c: 'git branch -D feature-login', d: 'Force-deletes a branch even if it contains unmerged commits.', e: 'Abandoning an experiment. The commits survive in the reflog for a while, so recovery is still possible.' },
    { c: 'git branch --merged', d: 'Lists branches whose work is already contained in the current branch.', e: 'Everything listed (except main) is safe to delete.' },
    { c: 'git branch --no-merged', d: 'Lists branches with commits that have not landed on the current branch.', e: 'Pre-release check: is there finished work sitting on a branch that nobody merged?' },
    { c: 'git branch -u origin/main', d: 'Sets the upstream branch for the current branch, so plain push and pull know where to go.', e: 'Fixes the "there is no tracking information for the current branch" error.' },
    { c: 'git branch --unset-upstream', d: 'Removes the tracking relationship between a local and remote branch.', e: 'The remote branch was deleted and Git keeps complaining about it every time you pull.' }
  ]
},
{
  id: "merge",
  label: "Merging & conflicts",
  tag: "branching",
  blurb: "Merging brings two lines of work back together. Conflicts are not errors — they are Git asking you to make a decision it cannot make.",
  commands: [
    { c: 'git merge feature-login', d: 'Merges the named branch into the branch you are currently on.', e: 'Always switch to the destination branch first. To put a feature into main: switch to main, pull, then merge the feature.', x: 'git switch main\ngit pull origin main\ngit merge feat/login\ngit push origin main' },
    { c: 'git merge --no-ff feature-login', d: 'Always creates a merge commit, even when a fast-forward would have been possible.', e: 'Keeps a visible record that a feature branch existed and when it landed. Many teams require this on main.' },
    { c: 'git merge --ff-only feature-login', d: 'Merges only if it can be done by moving the branch pointer forward; otherwise it stops.', e: 'Enforces a strictly linear history — if it fails, you rebase first and try again.' },
    { c: 'git merge --squash feature-login', d: 'Applies all of the branch\'s changes to your working tree as one staged change set, without committing.', e: 'Twenty messy work-in-progress commits become one clean commit on main. You still need to run git commit afterwards.', x: 'git switch main\ngit merge --squash feat/login\ngit commit -m "feat: add login flow"' },
    { c: 'git merge -m "Merge release 1.2 into main" release/1.2', d: 'Supplies your own merge commit message instead of the generated one.', e: 'Recording context about why a merge happened, especially for release merges.' },
    { c: 'git merge --abort', d: 'Cancels an in-progress merge and puts everything back exactly as it was.', e: 'The conflict is bigger than you expected and you want to regroup. Completely safe.' },
    { c: 'git merge --continue', d: 'Finishes a merge after you have resolved and staged all conflicted files.', e: 'The last step of conflict resolution. Running git commit does the same thing.' },
    { c: 'git merge -X ours feature', d: 'Resolves conflicting hunks automatically in favour of your current branch, while still merging everything non-conflicting.', e: 'Merging a long-dead branch where you know your side is authoritative for any overlap.' },
    { c: 'git merge -X theirs feature', d: 'Resolves conflicting hunks in favour of the incoming branch.', e: 'Pulling in a vendor or generated-code branch that should always win.' },
    { c: 'git merge --strategy=ours old-branch', d: 'Records a merge but keeps your content entirely, discarding the other branch\'s changes.', e: 'Marking an obsolete branch as merged so it stops showing in --no-merged, without importing its code.' },
    { c: 'git checkout --ours config.json', d: 'During a conflict, takes your branch\'s whole version of a file.', e: 'Lock files and generated files are usually not worth merging by hand — pick one side, then regenerate.', x: 'git checkout --ours package-lock.json\ngit add package-lock.json\n# better still: git checkout --ours, then npm install to regenerate' },
    { c: 'git checkout --theirs config.json', d: 'During a conflict, takes the incoming branch\'s whole version of a file.', e: 'The other side rewrote the file entirely and yours is stale.' },
    { c: 'git mergetool', d: 'Opens a three-way visual merge tool for each conflicted file.', e: 'Complex conflicts are far easier to reason about with base, ours and theirs side by side.', x: 'git config --global merge.tool vscode\ngit config --global mergetool.vscode.cmd "code --wait $MERGED"\ngit mergetool' },
    { c: 'git diff --name-only --diff-filter=U', d: 'Lists exactly which files are still conflicted.', e: 'Your checklist during a large merge — when this prints nothing, you are ready to continue.' },
    { c: 'git log --merge -p file.js', d: 'Shows the commits from both sides that touched a conflicted file.', e: 'Understanding why a conflict exists before deciding how to resolve it.' },
    { c: 'git merge-base main feature', d: 'Prints the commit where two branches diverged.', e: 'Useful in scripts, and for building a diff of only the work unique to your branch.' }
  ]
},
{
  id: "rebase",
  label: "Rebasing",
  tag: "branching",
  blurb: "Rebase rewrites your commits onto a new base to keep history linear. Powerful on your own branch, dangerous on shared ones.",
  commands: [
    { c: 'git rebase main', d: 'Replays your branch\'s commits on top of the latest main, as if you had branched today.', e: 'Your feature branch is a week behind. Rebasing gives you a clean, linear pull request with no merge commit noise.', x: 'git switch main && git pull\ngit switch feat/login\ngit rebase main\n# resolve any conflicts, then\ngit push --force-with-lease' },
    { c: 'git rebase -i HEAD~5', d: 'Interactive rebase: opens an editor listing the last five commits so you can reorder, squash, reword or drop them.', e: 'Cleaning up a messy branch before review — turning "wip", "wip2", "fix typo" into two meaningful commits.', x: 'pick   a1b2c3  feat: add login form\nsquash d4e5f6  wip\nsquash 7g8h9i  fix typo\nreword j1k2l3  add validation\ndrop   m4n5o6  debug logging\n\n# p pick   r reword  e edit\n# s squash f fixup   d drop\n# x exec   b break' },
    { c: 'git rebase -i --autosquash HEAD~10', d: 'Automatically arranges any --fixup and --squash commits next to their targets in the todo list.', e: 'The clean way to address review feedback: make fixup commits as you go, then autosquash them all at the end.' },
    { c: 'git rebase --continue', d: 'Proceeds to the next commit after you have resolved conflicts and staged the fixes.', e: 'A rebase pauses at every conflicting commit, so you may run this several times in one rebase.' },
    { c: 'git rebase --skip', d: 'Drops the commit currently being applied and moves on.', e: 'The change is already present on the target branch, so replaying it produces an empty or duplicate commit.' },
    { c: 'git rebase --abort', d: 'Cancels the rebase and restores your branch exactly as it was before you started.', e: 'Your escape hatch. If a rebase turns into a wall of conflicts, abort and merge instead.' },
    { c: 'git rebase --onto main feature1 feature2', d: 'Moves the commits of feature2 that sit on top of feature1 onto main instead.', e: 'You branched off the wrong branch. This transplants only your commits without dragging feature1\'s work along.' },
    { c: 'git rebase --rebase-merges main', d: 'Rebases while preserving the shape of merge commits in your branch.', e: 'Rewriting a branch that itself contains merges, without flattening its structure.' },
    { c: 'git rebase -x "npm test" main', d: 'Runs a command after each replayed commit and stops if it fails.', e: 'Verifies that every commit in your branch independently passes tests — a requirement for bisect to work well later.' },
    { c: 'git rebase --edit-todo', d: 'Reopens the todo list mid-rebase so you can change your plan.', e: 'You realise halfway through that you wanted to squash two commits you had marked pick.' },
    { c: 'git pull --rebase', d: 'Fetches remote commits and replays your local ones on top, instead of creating a merge commit.', e: 'The everyday way to sync a shared branch without polluting history with "Merge branch main of github.com…" commits.' },
    { c: 'git push --force-with-lease', d: 'Pushes rewritten history, but refuses if the remote has commits you have not seen.', e: 'Mandatory after any rebase of a pushed branch. Unlike --force, it will not silently delete a teammate\'s work.' },
    { c: 'git rebase --root -i', d: 'Includes the very first commit in an interactive rebase.', e: 'Rewriting a repository from the beginning, for example to fix the author email on every commit.' }
  ]
},
{
  id: "remotes",
  label: "Remotes",
  tag: "remote",
  blurb: "A remote is a named URL for another copy of the repository. origin is yours; upstream is usually the project you forked.",
  commands: [
    { c: 'git remote -v', d: 'Lists every configured remote with its fetch and push URLs.', e: 'First thing to check when a push goes to the wrong place or asks for credentials you do not expect.' },
    { c: 'git remote add origin git@github.com:you/repo.git', d: 'Connects your local repository to a remote URL under the name origin.', e: 'The step after git init: create an empty repo on GitHub, add it as origin, then push.', x: 'git init\ngit add .\ngit commit -m "chore: initial commit"\ngit branch -M main\ngit remote add origin git@github.com:you/repo.git\ngit push -u origin main' },
    { c: 'git remote add upstream https://github.com/original/repo.git', d: 'Adds a second remote pointing at the project you forked from.', e: 'The standard open-source setup: origin is your fork, upstream is the original — you fetch from upstream and push to origin.' },
    { c: 'git remote set-url origin git@github.com:you/repo.git', d: 'Changes the URL of an existing remote.', e: 'Switching from HTTPS to SSH so you stop being asked for a personal access token on every push.' },
    { c: 'git remote rename origin old-origin', d: 'Renames a remote.', e: 'Reorganising when you add a second host, such as a self-hosted GitLab mirror alongside GitHub.' },
    { c: 'git remote remove upstream', d: 'Deletes a remote and its tracking branches.', e: 'The upstream project was archived and you no longer need to sync with it.' },
    { c: 'git remote show origin', d: 'Prints a detailed report: the default branch, which local branches track which remote ones, and what is stale.', e: 'The clearest single view of how your local repository relates to the server.' },
    { c: 'git remote prune origin', d: 'Deletes local references to remote branches that no longer exist on the server.', e: 'After a few months of merged pull requests, git branch -r is full of ghosts. This clears them.', x: 'git remote prune origin --dry-run   # preview\ngit remote prune origin             # do it\ngit fetch --prune                   # same effect while fetching' },
    { c: 'git remote get-url origin', d: 'Prints just the URL of a remote.', e: 'Useful inside scripts that need to know where the repository lives.' },
    { c: 'git remote set-head origin -a', d: 'Updates your local idea of which branch is the remote\'s default.', e: 'The project renamed master to main and origin/HEAD still points at the old one.' }
  ]
},
{
  id: "sync",
  label: "Push, pull & fetch",
  tag: "remote",
  blurb: "Fetch downloads. Merge integrates. Pull does both at once. Push sends your work up.",
  commands: [
    { c: 'git push', d: 'Sends the commits on your current branch to its upstream branch.', e: 'Works only once an upstream is set, which is why the first push on a new branch needs -u.' },
    { c: 'git push -u origin feature-login', d: 'Pushes the branch and remembers the link, so future pushes and pulls need no arguments.', e: 'The first push of any new branch. The -u is what makes plain git push work afterwards.' },
    { c: 'git push origin main', d: 'Pushes a specific branch to a specific remote, ignoring upstream settings.', e: 'Explicit and unambiguous — the safest form when you are working with several remotes.' },
    { c: 'git push --all origin', d: 'Pushes every local branch.', e: 'Migrating a repository to a new host, or backing up all your work at once.' },
    { c: 'git push --tags', d: 'Pushes all local tags to the remote.', e: 'Tags do not travel with a normal push. If your release does not appear on GitHub, this is why.' },
    { c: 'git push --follow-tags', d: 'Pushes your commits along with any annotated tags that point into them.', e: 'The tidy way to publish a release in a single command.' },
    { c: 'git push origin --delete feature-login', d: 'Deletes a branch on the remote.', e: 'Cleanup after a pull request is merged, if GitHub is not configured to do it automatically.' },
    { c: 'git push --force-with-lease', d: 'Overwrites the remote branch, but only if it still matches what you last fetched.', e: 'Always prefer this over --force. It is the difference between rewriting your own history and destroying somebody else\'s.' },
    { c: 'git push --force', d: 'Overwrites the remote branch unconditionally.', e: 'Genuinely destructive — it can erase commits a teammate pushed five minutes ago. Reach for --force-with-lease instead.' },
    { c: 'git push --dry-run', d: 'Shows what would be pushed without sending anything.', e: 'Peace of mind before pushing to a production or protected branch.' },
    { c: 'git push origin HEAD', d: 'Pushes the current branch to a remote branch of the same name, without typing it.', e: 'Convenient with long branch names like feat/user-profile-avatar-upload.' },
    { c: 'git fetch', d: 'Downloads new commits, branches and tags from the remote without changing any of your files.', e: 'Completely safe. Fetch first, look at what arrived, then decide whether to merge or rebase.', x: 'git fetch origin\ngit log HEAD..origin/main --oneline   # what is new upstream\ngit diff HEAD origin/main             # what would change\ngit merge origin/main                 # apply it' },
    { c: 'git fetch --all', d: 'Fetches from every configured remote.', e: 'In a fork workflow, updates both origin and upstream in one go.' },
    { c: 'git fetch --prune', d: 'Fetches and simultaneously removes tracking branches that were deleted on the server.', e: 'Worth aliasing — it keeps your branch list honest. Set fetch.prune true to make it automatic.' },
    { c: 'git pull', d: 'Runs fetch and then merge in one step.', e: 'Convenient, but it hides what is arriving. Many developers prefer fetch, inspect, then merge.' },
    { c: 'git pull --rebase', d: 'Fetches, then replays your local commits on top of the remote ones.', e: 'Keeps a shared branch linear. Set it as the default with git config --global pull.rebase true.' },
    { c: 'git pull --ff-only', d: 'Pulls only if it can fast-forward, refusing to create a merge commit.', e: 'A safety net that tells you when your branch has diverged, instead of quietly merging.' },
    { c: 'git pull --autostash', d: 'Stashes your uncommitted work, pulls, then reapplies it.', e: 'Solves "cannot pull with rebase: you have unstaged changes" without doing the stash dance yourself.' }
  ]
},
{
  id: "fork",
  label: "Forks & contributing",
  tag: "remote",
  blurb: "The open-source loop: fork, branch, push, pull request, then keep your fork in sync.",
  commands: [
    { c: 'gh repo fork owner/repo --clone', d: 'Forks a repository to your account, clones it, and wires up origin and upstream automatically.', e: 'The fastest possible start on an open-source contribution — one command replaces five.' },
    { c: 'git remote add upstream https://github.com/original/repo.git', d: 'Manually points your clone at the original project so you can pull in its updates.', e: 'Do this immediately after cloning a fork, or your copy drifts out of date within days.' },
    { c: 'git fetch upstream && git merge upstream/main', d: 'Brings the original project\'s latest commits into your local main.', e: 'Run before starting any new contribution so you are building on current code.', x: 'git switch main\ngit fetch upstream\ngit merge upstream/main\ngit push origin main       # update your fork on GitHub' },
    { c: 'git rebase upstream/main', d: 'Replays your work on top of the upstream project rather than merging.', e: 'Most maintainers prefer this — your pull request then contains only your commits, cleanly stacked.' },
    { c: 'git switch -c fix/typo-in-readme upstream/main', d: 'Creates a contribution branch directly from the upstream default branch.', e: 'Guarantees your branch starts from current upstream code, even if your fork\'s main is stale.' },
    { c: 'gh repo sync you/repo --source original/repo', d: 'Updates your fork on GitHub from the original repository without cloning anything.', e: 'One command instead of the fetch, merge, push cycle.' },
    { c: 'git push -u origin fix/typo-in-readme', d: 'Pushes your contribution branch to your fork.', e: 'The step before opening a pull request. Never push contribution work to main.' },
    { c: 'gh pr create --repo original/repo --base main', d: 'Opens a pull request from your fork\'s branch against the original project.', e: 'Finishes the loop. Add a clear description and reference the issue it fixes with "Closes #123".' },
    { c: 'gh pr checkout 42', d: 'Checks out someone else\'s pull request locally, even from a fork.', e: 'Reviewing a contribution properly by running it, instead of only reading the diff on GitHub.' }
  ]
}
,
{
  id: "stash",
  label: "Stashing",
  tag: "rescue",
  blurb: "A stash is a drawer for unfinished work. Sweep your changes into it, do something else, then take them back out.",
  commands: [
    { c: 'git stash', d: 'Saves your uncommitted tracked changes and returns the working directory to a clean state.', e: 'A production bug lands while you are mid-feature. Stash, switch to main, fix, come back and pop.', x: 'git stash\ngit switch main\n# ...fix the bug, commit, push...\ngit switch feat/my-work\ngit stash pop' },
    { c: 'git stash push -m "half-done signup form"', d: 'Stashes with a description so you can tell your stashes apart later.', e: 'Once you have three stashes, unlabelled entries are useless. Always write a message.' },
    { c: 'git stash -u', d: 'Includes untracked files in the stash.', e: 'Without it, brand-new files stay in your working directory and follow you onto the other branch — usually not what you want.' },
    { c: 'git stash -a', d: 'Stashes everything, including files matched by .gitignore.', e: 'Rare, but useful when you need an absolutely pristine directory, for example to test a fresh build.' },
    { c: 'git stash -k', d: 'Stashes only the unstaged changes and keeps your staged ones in place.', e: 'You want to commit the staged part and test it in isolation, with the rest of your work set aside.' },
    { c: 'git stash -p', d: 'Interactively choose which chunks of change to stash.', e: 'Splitting one messy working tree into "the part I want to commit now" and "the part I will finish later".' },
    { c: 'git stash list', d: 'Shows all your stashes with their index and message.', e: 'Stashes are numbered newest-first: stash@{0} is the most recent.' },
    { c: 'git stash show -p stash@{1}', d: 'Displays the full diff of a particular stash.', e: 'Checking what is inside before you apply it, so you do not create conflicts blindly.' },
    { c: 'git stash apply', d: 'Reapplies the most recent stash but leaves it in the list.', e: 'Use when you want the same changes on two different branches.' },
    { c: 'git stash pop', d: 'Reapplies the most recent stash and deletes it from the list.', e: 'The normal way to resume work. If it conflicts, the stash is kept so nothing is lost.' },
    { c: 'git stash pop stash@{2}', d: 'Applies and removes a specific stash rather than the latest one.', e: 'Retrieving the right drawer when several are open.' },
    { c: 'git stash branch feat/resume stash@{0}', d: 'Creates a new branch from the commit the stash was made on, then applies the stash there.', e: 'The clean fix when a stash refuses to apply because the branch has moved on since you saved it.' },
    { c: 'git stash drop stash@{1}', d: 'Deletes a single stash.', e: 'Housekeeping after you have confirmed you no longer need it.' },
    { c: 'git stash clear', d: 'Deletes every stash.', e: 'Irreversible in practice — check git stash list first, because there is no confirmation prompt.' }
  ]
},
{
  id: "undo",
  label: "Undoing things",
  tag: "rescue",
  blurb: "The one page you will come back to. Revert is safe on shared history; reset rewrites it. Reflog is the net beneath both.",
  commands: [
    { c: 'git restore file.js', d: 'Discards uncommitted changes to a file, restoring the last committed version.', e: 'Undoing an experiment. There is no recovery — Git never saw those edits.' },
    { c: 'git restore --staged file.js', d: 'Unstages a file while keeping your changes.', e: 'The safe undo for an over-eager git add.' },
    { c: 'git reset --soft HEAD~1', d: 'Removes the last commit but leaves all its changes staged.', e: 'You committed too early. Everything is exactly as it was one second before you typed commit.' },
    { c: 'git reset HEAD~1', d: 'Removes the last commit and unstages its changes, leaving them in your working directory. This is the default, --mixed.', e: 'Undo a commit and re-split it into two smaller, better ones.' },
    { c: 'git reset --hard HEAD~1', d: 'Removes the last commit and permanently discards its changes.', e: 'Genuinely destructive. Only use when you are certain the work is worthless — and remember the reflog can still save you for a few weeks.' },
    { c: 'git reset --hard origin/main', d: 'Throws away all local commits and changes, making your branch identical to the remote.', e: 'The "start again from what is on the server" button when your local branch is beyond saving.' },
    { c: 'git reset --hard abc1234', d: 'Moves the branch to a specific commit and discards everything after it.', e: 'Rolling a local branch back to a known-good state.' },
    { c: 'git revert HEAD', d: 'Creates a brand-new commit that undoes the changes of a previous one.', e: 'The correct way to undo something already pushed. History is preserved, so nobody else\'s clone breaks.', x: 'git revert HEAD              # undo the last commit\ngit revert abc1234           # undo a specific commit\ngit push                     # safe: no force needed' },
    { c: 'git revert --no-commit HEAD~3..HEAD', d: 'Reverts a range of commits and stages the result without committing.', e: 'Rolling back a whole broken feature as a single, reviewable commit.' },
    { c: 'git revert -m 1 abc1234', d: 'Reverts a merge commit, using -m 1 to say "keep the branch I merged into".', e: 'A merged pull request broke production. This is the only correct way to undo a merge on a shared branch.' },
    { c: 'git reflog', d: 'Shows every position HEAD has occupied — including commits removed by reset, rebase or a deleted branch.', e: 'The most valuable recovery command in Git. Almost nothing is truly lost for the first 30–90 days.', x: 'git reflog\n# a1b2c3 HEAD@{0}: reset: moving to HEAD~3\n# d4e5f6 HEAD@{1}: commit: the work I just destroyed\ngit reset --hard HEAD@{1}     # bring it all back' },
    { c: 'git reflog show feat/login', d: 'Shows the history of where a specific branch pointer has been.', e: 'Recovering a branch you force-pushed over, or one you deleted with -D.' },
    { c: 'git clean -n', d: 'Dry run: lists the untracked files that git clean would delete.', e: 'Always run this before any clean. It costs nothing and prevents disasters.' },
    { c: 'git clean -fd', d: 'Deletes untracked files and directories.', e: 'Clearing generated output and stray files so you can test a genuinely clean build. Not recoverable — Git never tracked them.' },
    { c: 'git clean -fdx', d: 'Also deletes ignored files such as node_modules, .env and dist.', e: 'The nuclear reset. It will delete your .env file, so copy it somewhere first.' },
    { c: 'git clean -i', d: 'Interactive cleaning with a menu of what to delete.', e: 'The safe middle ground when you want most untracked files gone but not all of them.' },
    { c: 'git checkout HEAD~2 -- src/app.js', d: 'Restores one file from an older commit into your working directory.', e: 'Undoing a single bad change without touching the rest of the project.' },
    { c: 'git fsck --lost-found', d: 'Finds dangling commits and objects that no branch or tag points to.', e: 'Deep recovery when even the reflog has been pruned.' }
  ]
},
{
  id: "cherry",
  label: "Cherry-pick & patches",
  tag: "rescue",
  blurb: "Move individual commits between branches, or ship changes as files when there is no shared remote.",
  commands: [
    { c: 'git cherry-pick abc1234', d: 'Copies a single commit from anywhere in the repository onto your current branch.', e: 'A bug fix landed on develop and production needs it now, without the twenty other unreleased commits around it.', x: 'git switch hotfix/1.2.1\ngit cherry-pick abc1234\ngit push origin hotfix/1.2.1' },
    { c: 'git cherry-pick abc1234 def5678', d: 'Applies several specific commits in the order you list them.', e: 'Pulling three related fixes out of a feature branch into a release branch.' },
    { c: 'git cherry-pick abc1234^..def5678', d: 'Applies a range of commits, inclusive of the first one.', e: 'Moving a contiguous block of work. Without the ^, the first commit is excluded.' },
    { c: 'git cherry-pick -x abc1234', d: 'Adds a line to the message recording which commit this was copied from.', e: 'Essential on release branches so anyone reading the history can trace the change back to its original.' },
    { c: 'git cherry-pick -n abc1234', d: 'Applies the changes to your working tree and stages them, but does not commit.', e: 'You want to adapt the change before committing it, or combine several picks into one commit.' },
    { c: 'git cherry-pick -e abc1234', d: 'Opens the editor so you can rewrite the commit message as you pick.', e: 'The original message referenced a branch or ticket that means nothing on this branch.' },
    { c: 'git cherry-pick --continue', d: 'Resumes after you have resolved conflicts from a pick.', e: 'Cherry-picking across diverged branches frequently conflicts — this is the normal follow-up.' },
    { c: 'git cherry-pick --abort', d: 'Cancels the operation and restores your branch.', e: 'The commit does not apply cleanly and it is easier to make the change by hand.' },
    { c: 'git cherry-pick -m 1 abc1234', d: 'Cherry-picks a merge commit, choosing which parent to treat as the mainline.', e: 'Copying an entire merged feature to another release line in one commit.' },
    { c: 'git format-patch -3', d: 'Exports the last three commits as numbered .patch files, complete with author and message.', e: 'Contributing to projects that accept patches by email, such as the Linux kernel.', x: 'git format-patch -3 -o patches/\n# creates patches/0001-....patch etc.' },
    { c: 'git format-patch main..feature', d: 'Creates one patch file per commit that exists on feature but not main.', e: 'Handing your entire branch to someone who cannot access your remote.' },
    { c: 'git am 0001-fix.patch', d: 'Applies a patch file and creates a commit, preserving the original author.', e: 'The receiving end of format-patch. Use --3way if it does not apply cleanly.' },
    { c: 'git apply --check changes.patch', d: 'Tests whether a patch applies cleanly, without changing anything.', e: 'Always run this first — it turns a messy half-applied patch into a simple yes or no.' },
    { c: 'git diff > my-changes.patch', d: 'Writes your uncommitted changes into a plain patch file.', e: 'Sharing a work-in-progress fix in a chat or issue thread when you cannot push a branch.', x: 'git diff > my-changes.patch\n# on the other machine:\ngit apply my-changes.patch' }
  ]
},
{
  id: "tags",
  label: "Tags & releases",
  tag: "release",
  blurb: "A tag is a permanent name for a commit. It is how a pile of commits becomes v1.0.0.",
  commands: [
    { c: 'git tag', d: 'Lists all tags in the repository.', e: 'Checking which versions have already been released before you cut a new one.' },
    { c: 'git tag v1.0.0', d: 'Creates a lightweight tag — just a name pointing at the current commit, with no extra data.', e: 'Fine for a personal bookmark, but use an annotated tag for anything you publish.' },
    { c: 'git tag -a v1.0.0 -m "First stable release"', d: 'Creates an annotated tag: a real object storing the tagger, date and message.', e: 'The correct choice for releases. GitHub uses the message as the release description.', x: 'git tag -a v1.2.0 -m "Release 1.2.0\n\nAdded\n- TOTP two-factor login\n- CSV export\n\nFixed\n- Session timeout on refresh"' },
    { c: 'git tag -a v1.0.1 abc1234 -m "Patch release"', d: 'Tags an older commit rather than the current one.', e: 'You forgot to tag the release commit and have already moved on.' },
    { c: 'git tag -s v1.0.0 -m "Signed release"', d: 'Creates a GPG-signed tag that others can cryptographically verify.', e: 'Standard practice for security-sensitive software, so users can prove the release came from you.' },
    { c: 'git tag -v v1.0.0', d: 'Verifies the signature on a signed tag.', e: 'Confirming a downloaded release genuinely came from the maintainer.' },
    { c: 'git tag -l "v1.*"', d: 'Lists tags matching a pattern.', e: 'Filtering to a single major version when the repository has hundreds of tags.' },
    { c: 'git tag -l --sort=-version:refname', d: 'Sorts tags by version number, newest first, understanding that v1.10 comes after v1.9.', e: 'Plain alphabetical sorting gets version numbers wrong. This one does not.' },
    { c: 'git tag -n5', d: 'Lists tags along with the first five lines of each message.', e: 'A quick changelog straight from your tag history.' },
    { c: 'git push origin v1.0.0', d: 'Pushes a single tag to the remote.', e: 'Tags are not included in a normal push. On GitHub, pushing a tag is what triggers a release workflow.' },
    { c: 'git push --tags', d: 'Pushes every local tag that the remote does not have.', e: 'Catching up after tagging several releases locally.' },
    { c: 'git tag -d v1.0.0', d: 'Deletes a local tag.', e: 'You tagged the wrong commit and have not pushed yet.' },
    { c: 'git push origin --delete v1.0.0', d: 'Deletes a tag from the remote.', e: 'Retracting a broken release. Do it fast — anyone who already fetched still has the tag.' },
    { c: 'git checkout v1.0.0', d: 'Checks out the exact code of a released version in detached HEAD state.', e: 'Reproducing a bug report against the version a user is actually running.' },
    { c: 'git switch -c hotfix/1.0.1 v1.0.0', d: 'Creates a branch starting from a release tag.', e: 'The standard hotfix pattern: patch the released code, not the current development tip.' },
    { c: 'git archive --format=zip --prefix=app-1.0.0/ v1.0.0 > app-1.0.0.zip', d: 'Exports the files of a tagged version as a zip, without any Git metadata.', e: 'Producing a clean source download for people who just want the code.' },
    { c: 'git describe --tags --abbrev=0', d: 'Prints the most recent tag reachable from the current commit.', e: 'Working out the previous version in a release script so you can generate the changelog since then.', x: 'PREV=$(git describe --tags --abbrev=0)\ngit log $PREV..HEAD --oneline --no-merges > CHANGELOG-new.md' }
  ]
},
{
  id: "advanced",
  label: "Worktrees, submodules & LFS",
  tag: "advanced",
  blurb: "Three tools for when one folder, one repository and small files stop being enough.",
  commands: [
    { c: 'git worktree add ../hotfix main', d: 'Checks out another branch into a second folder that shares the same repository.', e: 'Fix an urgent bug in a separate folder while your feature branch stays untouched — no stashing, no rebuilding node_modules.', x: 'git worktree add ../myapp-hotfix -b hotfix/login main\ncd ../myapp-hotfix\n# fix, commit, push\ncd -\ngit worktree remove ../myapp-hotfix' },
    { c: 'git worktree list', d: 'Shows every working tree attached to the repository and which branch each has checked out.', e: 'Remembering where you parked that second checkout.' },
    { c: 'git worktree remove ../hotfix', d: 'Detaches and deletes a worktree folder.', e: 'Cleanup when the hotfix is shipped. Use git worktree prune to clear stale entries after deleting a folder manually.' },
    { c: 'git submodule add https://github.com/user/lib.git libs/lib', d: 'Embeds another Git repository inside yours at a pinned commit.', e: 'Sharing a component library across several projects while keeping its history separate.' },
    { c: 'git submodule update --init --recursive', d: 'Downloads and checks out the correct commit for every submodule, including nested ones.', e: 'The command that fixes empty submodule folders after a plain clone.' },
    { c: 'git clone --recurse-submodules url', d: 'Clones a repository and initialises all of its submodules in one step.', e: 'Always use this on projects that use submodules — it saves the confusing "why is this folder empty?" moment.' },
    { c: 'git submodule update --remote --merge', d: 'Pulls the latest commits for each submodule from its own remote.', e: 'Upgrading a shared library dependency to its newest version.' },
    { c: 'git submodule status', d: 'Shows the commit each submodule is currently pinned to.', e: 'A plus sign means the submodule has moved and the parent repo has not recorded it yet.' },
    { c: 'git lfs install', d: 'Sets up Git Large File Storage on your machine.', e: 'One-time setup before working with any repository that stores images, video, models or datasets.' },
    { c: 'git lfs track "*.psd"', d: 'Tells LFS to store matching files outside the repository, leaving a small pointer in Git.', e: 'Keeps a design-heavy repo from ballooning to gigabytes. Remember to commit the .gitattributes file it writes.', x: 'git lfs install\ngit lfs track "*.psd"\ngit lfs track "*.mp4"\ngit add .gitattributes\ngit commit -m "chore: track binaries with LFS"' },
    { c: 'git lfs ls-files', d: 'Lists the files currently managed by LFS.', e: 'Confirming your tracking rules are actually catching the big files.' },
    { c: 'git lfs migrate import --include="*.zip"', d: 'Rewrites existing history to move already-committed large files into LFS.', e: 'Rescuing a repository that is slow to clone because someone committed a 300 MB archive last year. This rewrites history, so coordinate with your team.' },
    { c: 'git sparse-checkout set src/ docs/', d: 'Checks out only the directories you name, even though the full history is present.', e: 'Working on one service inside a huge monorepo without materialising the other two hundred folders.', x: 'git clone --filter=blob:none --sparse url\ncd repo\ngit sparse-checkout set apps/web packages/ui' },
    { c: 'git bundle create repo.bundle --all', d: 'Packs the entire repository into a single transferable file.', e: 'Moving a repository onto an air-gapped machine, or emailing a full project to someone. Clone it back with git clone repo.bundle.' },
    { c: 'git notes add -m "Deployed to prod 2026-05-01" HEAD', d: 'Attaches a note to a commit without changing the commit itself.', e: 'Recording deployment or review metadata after the fact, since commit messages are immutable.' }
  ]
},
{
  id: "hooks",
  label: "Hooks & automation",
  tag: "automation",
  blurb: "Hooks are scripts Git runs at key moments. They are how you stop bad code before it ever reaches the remote.",
  commands: [
    { c: 'ls .git/hooks/', d: 'Lists the sample hook scripts Git creates in every repository.', e: 'Rename any .sample file to remove the suffix and it becomes active. Hooks are local and never travel with a clone.' },
    { c: 'chmod +x .git/hooks/pre-commit', d: 'Makes a hook executable, which is required before Git will run it.', e: 'The most common reason a hook silently does nothing.' },
    { c: 'cat > .git/hooks/pre-commit', d: 'The pre-commit hook runs before a commit is created; a non-zero exit aborts it.', e: 'Blocking commits that fail linting or tests, so main never contains an obviously broken build.', x: '#!/bin/sh\nnpm run lint || { echo "Lint failed. Commit aborted."; exit 1; }\nnpm test  || { echo "Tests failed. Commit aborted."; exit 1; }\necho "Pre-commit checks passed."' },
    { c: 'cat > .git/hooks/pre-push', d: 'The pre-push hook runs before commits are sent to a remote.', e: 'A last line of defence against pushing straight to main.', x: '#!/bin/sh\nbranch=$(git symbolic-ref --short HEAD)\nif [ "$branch" = "main" ]; then\n  echo "Direct push to main is blocked. Open a pull request."\n  exit 1\nfi' },
    { c: 'cat > .git/hooks/commit-msg', d: 'The commit-msg hook receives the message file and can validate or reject it.', e: 'Enforcing Conventional Commits so your changelog tooling keeps working.', x: '#!/bin/sh\ngrep -qE "^(feat|fix|docs|style|refactor|test|chore)(\\(.+\\))?: .{1,60}$" "$1" || {\n  echo "Message must look like: feat(auth): add TOTP login"\n  exit 1\n}' },
    { c: 'git config --global core.hooksPath ~/.git-hooks', d: 'Points every repository at one shared hooks folder.', e: 'Applying your personal safety checks across all projects without copying scripts into each one.' },
    { c: 'npx husky init', d: 'Sets up Husky, which stores hooks in a committed .husky folder so the whole team gets them.', e: 'The standard solution to "hooks are not shared" in JavaScript projects — they install automatically with npm install.', x: 'npm install --save-dev husky\nnpx husky init\necho "npm test" > .husky/pre-commit\ngit add .husky && git commit -m "chore: add git hooks"' },
    { c: 'npx lint-staged', d: 'Runs linters only on the files that are staged, rather than the whole project.', e: 'Keeps the pre-commit hook fast enough that people do not start using --no-verify.' },
    { c: 'pre-commit install', d: 'The Python equivalent of Husky, configured through .pre-commit-config.yaml.', e: 'Language-agnostic hook management with a large library of ready-made checks, including secret scanning.' }
  ]
},
{
  id: "maintenance",
  label: "Performance & maintenance",
  tag: "automation",
  blurb: "Repositories get slow the same way houses get cluttered. These commands are the spring clean.",
  commands: [
    { c: 'git gc', d: 'Garbage collection: compresses loose objects and prunes unreachable ones.', e: 'Run it on a repository that has become sluggish after months of heavy branching.' },
    { c: 'git gc --aggressive --prune=now', d: 'A slower, thorough repack that discards unreachable objects immediately.', e: 'Reclaiming real disk space after removing large files. Warning: it also drops reflog entries, so your recovery net goes with it.' },
    { c: 'git maintenance start', d: 'Registers the repository for automatic background upkeep on a schedule.', e: 'Set it once on large repos and everyday commands stay fast without you thinking about it.' },
    { c: 'git repack -ad', d: 'Repacks all objects into a single optimised pack file.', e: 'Shrinking a repository before archiving or mirroring it.' },
    { c: 'git count-objects -vH', d: 'Reports object counts and total size in human-readable units.', e: 'The before-and-after measurement when you are trying to shrink a repository.' },
    { c: 'git config core.preloadindex true', d: 'Loads the index in parallel, speeding up status and diff on large trees.', e: 'Noticeably faster on Windows and on repositories with tens of thousands of files.' },
    { c: 'git config core.untrackedCache true', d: 'Caches the untracked-file scan so git status does not re-walk every directory.', e: 'Turns a multi-second git status into an instant one in a big monorepo.' },
    { c: 'git config feature.manyFiles true', d: 'Enables a bundle of settings tuned for repositories with very large working trees.', e: 'A one-line performance upgrade for monorepos.' },
    { c: 'git verify-pack -v .git/objects/pack/*.idx | sort -k 3 -n | tail -10', d: 'Lists the ten largest objects in the repository.', e: 'Finding the specific committed file that is making your clone take twenty minutes.' },
    { c: 'git prune', d: 'Deletes unreachable objects from the object database.', e: 'Called automatically by gc; run it directly only when you know what you are removing.' },
    { c: 'git fsck', d: 'Checks the repository for corruption and inconsistent objects.', e: 'Diagnosing strange errors after a disk failure or an interrupted clone.' }
  ]
},
{
  id: "security",
  label: "Security & secrets",
  tag: "automation",
  blurb: "Signing proves who wrote a commit. Everything else here is about keeping credentials out of history — and getting them out when they slip in.",
  commands: [
    { c: 'ssh-keygen -t ed25519 -C "you@example.com"', d: 'Generates a modern SSH key pair for authenticating with GitHub.', e: 'The setup step that ends personal-access-token prompts forever. Add the .pub half to GitHub, keep the private half secret.', x: 'ssh-keygen -t ed25519 -C "you@example.com"\neval "$(ssh-agent -s)"\nssh-add ~/.ssh/id_ed25519\ncat ~/.ssh/id_ed25519.pub    # paste into GitHub > Settings > SSH keys\nssh -T git@github.com        # verify' },
    { c: 'ssh -T git@github.com', d: 'Tests whether your SSH key is working with GitHub.', e: 'A friendly greeting with your username means the key is set up correctly.' },
    { c: 'gpg --full-generate-key', d: 'Creates a GPG key pair for signing commits and tags.', e: 'The first step towards the Verified badge on your commits.' },
    { c: 'gpg --list-secret-keys --keyid-format=long', d: 'Lists your GPG keys and their IDs.', e: 'You need the key ID for the next command.' },
    { c: 'git config --global user.signingkey YOUR_KEY_ID', d: 'Tells Git which key to sign with.', e: 'Pair it with commit.gpgsign so signing happens automatically.', x: 'git config --global user.signingkey 3AA5C34371567BD2\ngit config --global commit.gpgsign true\ngit config --global tag.gpgSign true\ngpg --armor --export 3AA5C34371567BD2   # add to GitHub > SSH and GPG keys' },
    { c: 'git log --show-signature -1', d: 'Displays the signature status of a commit.', e: 'Verifying that a signed commit really is signed before you trust it.' },
    { c: 'git config --global transfer.fsckObjects true', d: 'Makes Git validate objects during transfer, rejecting malformed or malicious ones.', e: 'A cheap hardening step for anyone who clones from unfamiliar sources.' },
    { c: 'git rm --cached .env && echo ".env" >> .gitignore', d: 'Stops tracking a secrets file and prevents it being re-added.', e: 'The immediate first aid. It does not remove the secret from earlier commits — you must also rotate the credential.', x: 'git rm --cached .env\necho ".env" >> .gitignore\ngit commit -m "chore: remove .env from tracking"\ngit push\n# then, always: rotate the leaked key/token/password' },
    { c: 'git log --all --full-history -- .env', d: 'Checks whether a sensitive file has ever existed anywhere in history.', e: 'Auditing a repository before you make it public.' },
    { c: 'git filter-repo --path .env --invert-paths', d: 'Rewrites the entire history to remove a file from every commit. The modern replacement for filter-branch.', e: 'Real cleanup after a secret leak. It changes every commit hash, so everyone must re-clone — and the credential still needs rotating.', x: 'pip install git-filter-repo\ngit filter-repo --path .env --invert-paths\ngit remote add origin git@github.com:you/repo.git\ngit push --force --all\ngit push --force --tags' },
    { c: 'java -jar bfg.jar --delete-files .env repo.git', d: 'BFG Repo-Cleaner: a fast, simpler tool for purging files or strings from history.', e: 'Easier than filter-repo when you just need "delete this file everywhere" or "replace this password string".', x: 'git clone --mirror git@github.com:you/repo.git\njava -jar bfg.jar --replace-text passwords.txt repo.git\ncd repo.git && git reflog expire --expire=now --all && git gc --prune=now\ngit push --force' },
    { c: 'gitleaks detect --source .', d: 'Scans the working tree and history for hard-coded secrets.', e: 'Run it in CI so a leaked API key fails the build instead of reaching production.' },
    { c: 'gh secret set API_KEY', d: 'Stores an encrypted secret in the repository for GitHub Actions to use.', e: 'The correct home for deployment tokens and database URLs — never a committed file.' }
  ]
}
,
{
  id: "ghcli",
  label: "GitHub CLI",
  tag: "github",
  blurb: "gh brings issues, pull requests, releases and Actions into your terminal. No tab switching, no clicking.",
  commands: [
    { c: 'gh auth login', d: 'Signs the CLI in to your GitHub account and can also configure Git to use those credentials.', e: 'The one-time setup. Choose SSH if you already have a key, HTTPS if you do not.' },
    { c: 'gh auth status', d: 'Shows which account you are signed in as and what scopes the token has.', e: 'Diagnosing a "permission denied" error before you start guessing.' },
    { c: 'gh repo create my-project --public --source=. --push', d: 'Creates a GitHub repository from your existing local folder, adds it as origin and pushes.', e: 'Replaces the whole browser workflow — one command from local folder to live repo.', x: 'git init && git add . && git commit -m "chore: initial commit"\ngh repo create my-project --public --source=. --remote=origin --push' },
    { c: 'gh repo clone user/repo', d: 'Clones a repository using the shorthand name, no full URL needed.', e: 'Faster than copying URLs, and it configures the fork remotes for you when relevant.' },
    { c: 'gh repo view --web', d: 'Opens the current repository in your browser.', e: 'Jumping to the GitHub page for the repo you are standing in. gh browse does the same.' },
    { c: 'gh repo edit --description "Multi-tenant security scanner"', d: 'Updates repository settings such as description, homepage, topics and visibility.', e: 'Polishing a project page without leaving the terminal.', x: 'gh repo edit --description "..." --homepage "https://demo.app" \\\n  --add-topic security --add-topic fastapi' },
    { c: 'gh issue list --assignee @me', d: 'Lists open issues assigned to you.', e: 'Your morning to-do list, straight in the terminal.' },
    { c: 'gh issue create --title "Login fails on Safari" --body "Steps to reproduce..."', d: 'Opens a new issue without a browser.', e: 'Capturing a bug the moment you find it, while the details are fresh.' },
    { c: 'gh issue view 42 --comments', d: 'Shows an issue and its whole discussion thread.', e: 'Catching up on context before you start working on the fix.' },
    { c: 'gh issue close 42 --comment "Fixed in v1.2.1"', d: 'Closes an issue with a closing comment.', e: 'Wrapping up cleanly after a release.' },
    { c: 'gh pr create --fill', d: 'Opens a pull request, using your branch\'s commits to fill the title and body automatically.', e: 'The fastest possible PR when your commit messages are already good.', x: 'gh pr create --fill\ngh pr create --title "feat: add TOTP login" --body "Closes #42" --base develop\ngh pr create --draft   # open early for feedback' },
    { c: 'gh pr list --state open', d: 'Lists pull requests with their numbers, titles and branch names.', e: 'Seeing what is waiting for review across the team.' },
    { c: 'gh pr checkout 42', d: 'Checks out a pull request as a local branch, even from a fork.', e: 'The right way to review: run the code, not just read the diff.' },
    { c: 'gh pr diff 42', d: 'Prints the full diff of a pull request in your terminal.', e: 'Skimming a change without loading a browser tab.' },
    { c: 'gh pr review 42 --approve -b "Looks good, ship it"', d: 'Submits a review with an approval, comment or change request.', e: 'Unblocking a teammate in seconds.', x: 'gh pr review 42 --approve -b "LGTM"\ngh pr review 42 --request-changes -b "Needs input validation on line 40"\ngh pr review 42 --comment -b "One question about the retry logic"' },
    { c: 'gh pr merge 42 --squash --delete-branch', d: 'Merges a pull request, squashing its commits into one and deleting the branch afterwards.', e: 'The standard clean merge. Swap --squash for --rebase or --merge depending on team policy.' },
    { c: 'gh pr status', d: 'Shows the state of your own pull requests, including CI checks and review status.', e: 'One glance tells you what is blocked and what is ready to merge.' },
    { c: 'gh pr ready 42', d: 'Marks a draft pull request as ready for review.', e: 'The signal that you have finished iterating and want eyes on it.' },
    { c: 'gh release create v1.2.0 --generate-notes', d: 'Publishes a GitHub release and writes the notes from merged pull requests automatically.', e: 'Generated release notes are better than most hand-written ones and take no time at all.', x: 'gh release create v1.2.0 --generate-notes\ngh release create v1.2.0 dist/*.zip --title "Version 1.2.0" --notes-file NOTES.md\ngh release create v1.3.0-beta --prerelease' },
    { c: 'gh release upload v1.2.0 dist/app.zip', d: 'Attaches build artifacts to an existing release.', e: 'Shipping compiled binaries or installers alongside the source.' },
    { c: 'gh gist create notes.md --public', d: 'Publishes a file as a GitHub gist.', e: 'Sharing a snippet or a log file with a permanent link instead of pasting it into chat.' },
    { c: 'gh api repos/:owner/:repo/stargazers', d: 'Calls any GitHub REST endpoint with your credentials already applied.', e: 'The escape hatch for anything the CLI does not wrap directly.' },
    { c: 'gh browse issues', d: 'Opens a specific page of the current repository in your browser.', e: 'Quick jumps: gh browse pulls, gh browse settings, gh browse -c for the current commit.' }
  ]
},
{
  id: "actions",
  label: "GitHub Actions",
  tag: "github",
  blurb: "CI/CD that lives in your repository. Push code, and a machine tests, builds and deploys it.",
  commands: [
    { c: 'gh workflow list', d: 'Lists the workflows defined in .github/workflows.', e: 'Getting oriented in a repository whose CI setup you did not write.' },
    { c: 'gh workflow run deploy.yml', d: 'Manually triggers a workflow that has a workflow_dispatch trigger.', e: 'Deploying on demand without pushing an empty commit.', x: 'gh workflow run deploy.yml -f environment=production -f version=1.2.0' },
    { c: 'gh run list --workflow=ci.yml', d: 'Shows recent runs of a workflow with their status and duration.', e: 'Checking whether the pipeline is green before you ask for a review.' },
    { c: 'gh run watch', d: 'Follows the current run live in your terminal.', e: 'Watching a deploy finish without refreshing a browser tab.' },
    { c: 'gh run view 1234567 --log-failed', d: 'Prints the logs of only the steps that failed.', e: 'Goes straight to the error instead of scrolling through 4,000 lines of successful output.' },
    { c: 'gh run rerun 1234567 --failed', d: 'Re-runs only the failed jobs of a previous run.', e: 'Flaky network test? Retry it without re-running the entire matrix.' },
    { c: 'gh run download 1234567', d: 'Downloads the artifacts a workflow produced.', e: 'Grabbing a build, a coverage report or a screenshot bundle from CI.' },
    { c: 'cat > .github/workflows/ci.yml', d: 'A workflow file: triggers at the top, then jobs made of steps.', e: 'The starting CI pipeline for almost any Node project — install, lint, test, build on every push and pull request.', x: 'name: CI\non:\n  push:\n    branches: [main, develop]\n  pull_request:\n    branches: [main]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: "20"\n          cache: npm\n      - run: npm ci\n      - run: npm run lint\n      - run: npm test\n      - run: npm run build' },
    { c: 'cat > .github/workflows/release.yml', d: 'A workflow triggered by pushing a tag, which builds and publishes a release.', e: 'Automating the whole release: push v1.2.0 and the artifacts appear on GitHub by themselves.', x: 'name: Release\non:\n  push:\n    tags: ["v*"]\n\njobs:\n  release:\n    runs-on: ubuntu-latest\n    permissions:\n      contents: write\n    steps:\n      - uses: actions/checkout@v4\n        with: { fetch-depth: 0 }\n      - run: npm ci && npm run build\n      - uses: softprops/action-gh-release@v2\n        with:\n          generate_release_notes: true\n          files: dist/*' },
    { c: 'gh secret set DATABASE_URL --body "postgres://..."', d: 'Stores an encrypted secret that workflows can read as ${{ secrets.DATABASE_URL }}.', e: 'Getting credentials into CI without ever committing them.' },
    { c: 'gh secret list', d: 'Lists the secret names configured for the repository (values are never shown).', e: 'Checking whether a deploy is failing because a secret was never set.' },
    { c: 'gh variable set NODE_VERSION --body "20"', d: 'Stores a non-sensitive configuration value for workflows.', e: 'Keeping environment settings out of the YAML so you can change them without a commit.' }
  ]
},
{
  id: "workflows",
  label: "Team workflows",
  tag: "github",
  blurb: "The command sequences that teams actually run. Pick one branching model and hold everyone to it.",
  commands: [
    { c: 'GitHub Flow — one main branch, short feature branches', d: 'main is always deployable. Every change is a short-lived branch that returns through a pull request. The simplest model, and the right default for web apps that deploy continuously.', e: 'Use it for almost everything: side projects, startups, and any team shipping several times a week.', x: 'git switch main && git pull\ngit switch -c feat/search-filters\n# work, commit in small steps\ngit push -u origin feat/search-filters\ngh pr create --fill\n# review, CI passes\ngh pr merge --squash --delete-branch\ngit switch main && git pull' },
    { c: 'Git Flow — main, develop, feature, release, hotfix', d: 'main holds released code only; develop is the integration branch; features branch off develop; release branches stabilise a version; hotfixes branch from main.', e: 'Best for versioned software with scheduled releases — desktop apps, mobile apps, anything a customer installs. Usually too heavy for a continuously deployed web app.', x: '# feature\ngit switch develop && git pull\ngit switch -c feature/user-profile\ngh pr create --base develop\n\n# release\ngit switch -c release/1.2.0 develop\n# bump version, update changelog, fix bugs only\ngit switch main && git merge --no-ff release/1.2.0\ngit tag -a v1.2.0 -m "Release 1.2.0"\ngit switch develop && git merge --no-ff release/1.2.0\ngit push origin main develop --follow-tags' },
    { c: 'Hotfix — patch production without shipping unreleased work', d: 'Branch from the released tag, not from the development tip, so the fix contains nothing else. Then merge it into both main and develop.', e: 'A security bug is live and develop is full of half-finished features you cannot ship yet.', x: 'git switch -c hotfix/1.2.1 v1.2.0\n# fix the bug\ngit commit -am "fix: patch session fixation in login"\ngit switch main && git merge --no-ff hotfix/1.2.1\ngit tag -a v1.2.1 -m "Hotfix 1.2.1"\ngit switch develop && git merge --no-ff hotfix/1.2.1\ngit push origin main develop --follow-tags' },
    { c: 'Trunk-based development — everyone commits to main', d: 'Branches live for hours, not days. Unfinished work hides behind feature flags rather than long-lived branches.', e: 'High-performing teams with strong automated tests. Merge conflicts almost disappear because nobody diverges for long.' },
    { c: 'Branch naming convention', d: 'A prefix plus a short description, matching the type prefixes used in your commit messages.', e: 'Consistent names make branch lists scannable and let automation route work correctly.', x: 'feat/user-authentication\nfix/login-redirect-loop\nchore/upgrade-node-20\ndocs/api-reference\nrefactor/extract-payment-service\nhotfix/1.2.1-session-bug' },
    { c: 'Keeping a long feature branch current', d: 'Rebase onto main regularly rather than merging main into your branch repeatedly.', e: 'Daily rebasing turns one enormous conflict at the end into small daily ones you can actually reason about.', x: 'git switch main && git pull\ngit switch feat/big-thing\ngit rebase main\n# resolve, then\ngit push --force-with-lease' },
    { c: 'Two people on one branch', d: 'Agree that everyone pulls with rebase and nobody force-pushes a shared branch.', e: 'Prevents the classic disaster where a force push erases the other person\'s morning.', x: 'git pull --rebase origin feat/shared\n# never: git push --force on a branch someone else uses\n# communicate before any history rewrite' },
    { c: 'A pull request worth reviewing', d: 'Keep it under roughly 400 lines, one concern per PR, with a description saying what changed and why.', e: 'Review quality collapses on large diffs. Small PRs get merged in hours; huge ones sit for days.', x: '## What\nAdds TOTP two-factor login for admin accounts.\n\n## Why\nCloses #42. Admin sessions were single-factor.\n\n## How to test\n1. Log in as admin\n2. Enable 2FA in settings\n3. Confirm the code is required on next login\n\n## Notes\nSecret is encrypted at rest; migration included.' }
  ]
},
{
  id: "fixes",
  label: "Common errors, fixed",
  tag: "rescue",
  blurb: "The messages that stop you mid-flow, and the exact command that clears each one.",
  commands: [
    { c: 'fatal: not a git repository', d: 'You are not inside a folder that Git tracks.', e: 'Either you are in the wrong directory, or the project was never initialised.', x: 'pwd                       # where am I?\ngit rev-parse --show-toplevel   # find the repo root\ngit init                  # if it genuinely has no repo yet' },
    { c: 'Updates were rejected because the remote contains work', d: 'Someone pushed commits you do not have yet, so your push would erase them.', e: 'The everyday collision. Pull first, then push — never reach for --force here.', x: 'git pull --rebase origin main\n# resolve conflicts if any\ngit push origin main' },
    { c: 'error: failed to push some refs (fetch first)', d: 'Same cause as above, usually on a first push to a repo that already has a README.', e: 'Rebase your local commits on top of the remote and push again.', x: 'git pull --rebase origin main\ngit push -u origin main' },
    { c: 'fatal: refusing to merge unrelated histories', d: 'Two repositories with no shared commit are being combined.', e: 'Happens when you create a repo on GitHub with a README and then push a local repo made separately.', x: 'git pull origin main --allow-unrelated-histories\n# resolve any conflicts, then commit' },
    { c: 'Your local changes would be overwritten by checkout', d: 'Switching branches would destroy uncommitted edits.', e: 'Commit them, or stash them — Git is protecting your work.', x: 'git stash push -m "wip"\ngit switch other-branch\n# later\ngit switch -\ngit stash pop' },
    { c: 'There is no tracking information for the current branch', d: 'The branch has never been linked to a remote branch.', e: 'Set the upstream once and plain push and pull work from then on.', x: 'git push -u origin $(git branch --show-current)' },
    { c: 'detached HEAD state', d: 'You are on a commit rather than a branch, so new commits belong to nothing.', e: 'Harmless if you were only looking. If you made commits here, create a branch before switching away.', x: 'git switch -c rescue-branch    # keep the work\ngit switch main                # or just leave' },
    { c: 'Permission denied (publickey)', d: 'GitHub does not recognise your SSH key.', e: 'Either the key is not loaded into the agent, or the public half is not on your GitHub account.', x: 'ssh -T git@github.com\nssh-add -l                     # is a key loaded?\nssh-add ~/.ssh/id_ed25519\ncat ~/.ssh/id_ed25519.pub      # add this to GitHub' },
    { c: 'CONFLICT (content): Merge conflict in file.js', d: 'Both branches changed the same lines and Git needs you to choose.', e: 'Open the file, delete the marker lines, keep the code you want, then stage and continue.', x: '<<<<<<< HEAD\nyour version\n=======\ntheir version\n>>>>>>> feature-branch\n\n# after editing:\ngit add file.js\ngit merge --continue      # or git rebase --continue' },
    { c: 'I committed to the wrong branch', d: 'The commits exist, they are just in the wrong place. Move them.', e: 'Very common — you forget to branch and commit straight onto main.', x: 'git branch feat/right-place        # bookmark the commits\ngit reset --hard HEAD~2            # rewind main (2 commits back)\ngit switch feat/right-place        # your work is here' },
    { c: 'I pushed a secret to GitHub', d: 'The credential is compromised the moment it is public, even for a minute.', e: 'Rotate the secret first; cleaning history is the second step, not the first.', x: '# 1. Revoke and reissue the key immediately\n# 2. Remove from tracking\ngit rm --cached .env && echo ".env" >> .gitignore\ngit commit -m "chore: remove secrets" && git push\n# 3. Purge from history\ngit filter-repo --path .env --invert-paths\ngit push --force --all' },
    { c: 'I deleted a branch that had work on it', d: 'The commits are still in the reflog and can be restored.', e: 'Almost nothing is truly gone for the first few weeks.', x: 'git reflog | grep "feat/lost-branch"\ngit switch -c feat/lost-branch abc1234' },
    { c: 'I ran git reset --hard and lost everything', d: 'Committed work is recoverable from the reflog; uncommitted work is not.', e: 'This is the argument for committing often, even messy work you plan to squash later.', x: 'git reflog\n# find the entry just before the reset\ngit reset --hard HEAD@{1}' },
    { c: 'Repository is too large / clone takes forever', d: 'Usually one big binary committed long ago and still sitting in every clone.', e: 'Find it, then either move it to LFS or purge it from history.', x: 'git count-objects -vH\ngit verify-pack -v .git/objects/pack/*.idx | sort -k 3 -n | tail -5\ngit lfs migrate import --include="*.mp4"' }
  ]
}
];

